78	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
79	
80	    /** Dedicated audit logger; one line is emitted per successful owner create. */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /**
84	     * The maximum number of owners a single city may contain. Once a city already holds this many
85	     * owners, any further create naming that city is rejected as a conflict.
86	     */
87	    private static final int MAX_OWNERS_PER_CITY = 50;
88	
89	    /**
90	     * The maximum number of owners that may be registered in a single day. Once this many owners
91	     * already carry today's registration date, any further create is rejected as too many requests.
92	     */
93	    private static final int MAX_OWNERS_PER_DAY = 100;
94	
95	    /**
96	     * The number of owners that must already be registered on today's business day before a response
97	     * carries a bulk-signup warning. Once more than this many owners already carry today's
98	     * registration date, responses set {@code bulkSignupWarning} true.
99	     */
100	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
