167	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
168	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
169	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
170	        this.clinicService.saveOwner(owner);
171	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
172	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
