267	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
268	            }
269	        }
270	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	    }
272	
273	    /**
274	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
275	     * offending field is collected so the caller learns exactly which values must be supplied.
276	     *
277	     * @param ownerFieldsDto the submitted owner payload
278	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
279	     *         telephone is missing or blank
280	     */
281	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
282	        List<String> missingFields = new ArrayList<>();
283	        if (isBlank(ownerFieldsDto.getFirstName())) {
284	            missingFields.add("firstName");
285	        }
286	        if (isBlank(ownerFieldsDto.getLastName())) {
287	            missingFields.add("lastName");
288	        }
289	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
290	            missingFields.add("address");
291	        }
292	        if (isBlank(ownerFieldsDto.getCity())) {
293	            missingFields.add("city");
294	        }
295	        if (isBlank(ownerFieldsDto.getTelephone())) {
296	            missingFields.add("telephone");
297	        }
298	        if (!missingFields.isEmpty()) {
299	            throw new MissingOwnerFieldsException(missingFields);
300	        }
301	    }
302	
303	    private boolean isBlank(String value) {
304	        return value == null || value.isBlank();
305	    }
306	
307	    /**
308	     * Counts the existing owners who, before this create, already share the given first and last name.
309	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
310	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
311	     * case or spacing still count as the same name.
312	     *
313	     * @param firstName the first name of the owner being created
314	     * @param lastName the last name of the owner being created
315	     * @return the number of existing owners sharing both names (zero when none)
316	     */
317	    private int countNamesakes(String firstName, String lastName) {
318	        String first = normalizeHouseholdField(firstName);
319	        String last = normalizeHouseholdField(lastName);
320	        return (int) this.clinicService.findAllOwners().stream()
321	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
322	                && normalizeHouseholdField(existing.getLastName()).equals(last))
323	            .count();
324	    }
325	
326	    /**
327	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
328	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
329	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
330	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
331	     * more owners the create is rejected as a conflict.
332	     *
333	     * @param city the city of the owner being created
334	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
335	     */
336	    /**
337	     * Rejects an owner create once the maximum number of owners have already been registered on the
338	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
339	     * which is always a business day (a weekend effective date is rolled forward to the following
340	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
341	     * business day the create is rejected as too many requests. Because a weekend effective date is
342	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
343	     *
344	     * @param businessDay the adjusted business day the owner being created would be registered on
345	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
346	     */
347	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
348	        long ownersOnDay = this.clinicService.findAllOwners().stream()
349	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
350	            .count();
351	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
352	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
353	        }
354	    }
355	
356	    /**
357	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
358	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
359	     * was supplied on the request or defaulted to the server's current date.
360	     *
361	     * @param date the effective registration date (supplied or defaulted)
362	     * @return the same date when it is a weekday, otherwise the following Monday
363	     */
364	    /**
365	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
366	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
367	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
368	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
369	     *
370	     * @return {@code true} when more than the threshold number of owners are already registered on
371	     *         today's business day, otherwise {@code false}
372	     */
373	    private boolean isBulkSignupWarningActive() {
374	        LocalDate today = toBusinessDay(LocalDate.now());
375	        long ownersToday = this.clinicService.findAllOwners().stream()
376	            .filter(existing -> today.equals(existing.getRegistrationDate()))
377	            .count();
378	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
379	    }
380	
381	    private LocalDate toBusinessDay(LocalDate date) {
382	        return switch (date.getDayOfWeek()) {
383	            case SATURDAY -> date.plusDays(2);
384	            case SUNDAY -> date.plusDays(1);
385	            default -> date;
386	        };
387	    }
388	
389	    private void rejectCityAtCapacity(String city) {
390	        String normalizedCity = normalizeHouseholdField(city);
391	        long ownersInCity = this.clinicService.findAllOwners().stream()
392	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
393	            .count();
394	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
395	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
396	        }
397	    }
398	
399	    /**
400	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
401	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
402	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
403	     * of owners already in that city (e.g. 'SYD-SMI-0007').
404	     *
405	     * @param city the owner's city
406	     * @param lastName the owner's last name
407	     * @return the formatted customer code
408	     */
409	    private String generateCustomerCode(String city, String lastName) {
410	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
411	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
412	        String normalizedCity = normalizeHouseholdField(city);
413	        int sequence = (int) this.clinicService.findAllOwners().stream()
414	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
415	            .count() + 1;
416	        return String.format("%s-%s-%04d", city3, last3, sequence);
417	    }
418	
419	    /**
420	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
421	     * customerCode is the owner's customer code and YY is the last two digits of the
422	     * registrationDate year (e.g. 'SMI-0007-M26').
423	     *
424	     * @param customerCode the owner's customer code
425	     * @param registrationDate the owner's registration date
426	     * @return the formatted membership number
427	     */
428	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
429	        String yy = String.format("%02d", registrationDate.getYear() % 100);
430	        return customerCode + "-M" + yy;
431	    }
432	
433	    /**
434	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
435	     * country calling code. Australia ('+61') uses 9 national digits and the North American
436	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
437	     * E.164 length (8 to 15 digits overall).
438	     */
439	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
440	        java.util.Map.of("61", 9, "1", 10);
441	
442	    /**
443	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
444	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
445	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
446	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
447	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
448	     * E.164 string is what gets stored and returned.
449	     *
450	     * @param telephone the raw telephone value from the request
451	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
452	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
453	     *         national number has the wrong length for its country code
454	     */
455	    private String normalizeTelephone(String telephone) {
456	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
457	        String e164;
458	        if (cleaned.startsWith("+")) {
459	            e164 = cleaned;
460	        } else {
461	            String national = cleaned;
462	            if (national.startsWith("0")) {
463	                national = national.substring(1);
464	            }
465	            e164 = "+61" + national;
466	        }
467	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
468	            throw new InvalidOwnerFieldsException(List.of("telephone"));
469	        }
470	        validateNationalNumberLength(e164);
471	        return e164;
472	    }
473	
474	    /**
475	     * Rejects an E.164 telephone whose national number does not have the exact length its country
476	     * calling code requires. The digits after the leading '+' are split into the longest matching
477	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
478	     * code is known and the national number's length differs from the required count the telephone is
479	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
480	     *
481	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
482	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
483	     */
484	    private void validateNationalNumberLength(String e164) {
485	        String digits = e164.substring(1);
486	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
487	            String countryCode = digits.substring(0, codeLength);
488	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
489	            if (requiredNationalLength != null) {
490	                int nationalLength = digits.length() - codeLength;
491	                if (nationalLength != requiredNationalLength) {
492	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
493	                }
494	                return;
495	            }
496	        }
497	    }
498	
499	    /**
500	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
501	     * left unset. When a value is present it must be a syntactically valid address; the normalized
502	     * form stored and returned is the value lower-cased.
503	     *
504	     * @param email the raw email value from the request, or {@code null} when none was supplied
505	     * @return the lower-cased email, or {@code null} when no email was supplied
506	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
507	     */
508	    private String normalizeEmail(String email) {
509	        if (email == null || email.isBlank()) {
510	            return null;
511	        }
512	        if (!EMAIL_PATTERN.matcher(email).matches()) {
513	            throw new InvalidOwnerFieldsException(List.of("email"));
514	        }
515	        return email.toLowerCase(Locale.ROOT);
516	    }
517	
518	    /**
519	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
520	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
521	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
522	     * normalized form is what gets stored, returned and used for every address comparison (the
523	     * required-field check, household duplicate detection and the shared household id).
524	     *
525	     * @param address the raw address value from the request, or {@code null}
526	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
527	     */
528	    private String normalizeAddress(String address) {
529	        if (address == null) {
530	            return "";
531	        }
532	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
533	        if (collapsed.isEmpty()) {
534	            return "";
535	        }
536	        String[] tokens = collapsed.split(" ");
537	        for (int i = 0; i < tokens.length; i++) {
538	            switch (tokens[i]) {
539	                case "ST" -> tokens[i] = "STREET";
540	                case "RD" -> tokens[i] = "ROAD";
541	                case "AVE" -> tokens[i] = "AVENUE";
542	                default -> { }
543	            }
544	        }
545	        return String.join(" ", tokens);
546	    }
547	
548	    /**
549	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
550	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
551	     * directly and is therefore independent of the punctuation a caller supplied.
552	     *
553	     * @param e164Telephone the E.164 telephone of the owner being created
554	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
555	     */
556	    private void rejectDuplicateTelephone(String e164Telephone) {
557	        boolean inUse = this.clinicService.findAllOwners().stream()
558	            .map(Owner::getTelephone)
559	            .filter(existing -> existing != null)
560	            .anyMatch(e164Telephone::equals);
561	        if (inUse) {
562	            throw new DuplicateOwnerTelephoneException(e164Telephone);
563	        }
564	    }
565	
566	    /**
567	     * Rejects an owner create whose lower-cased email is already used by any other owner. Owners
568	     * store their email in lower-cased form, so the uniqueness check compares these canonical values
569	     * directly and is therefore independent of the letter case a caller supplied. An owner with no
570	     * email supplied ({@code null}) is not subject to this check, since there is no value to collide.
571	     *
572	     * @param email the lower-cased email of the owner being created, or {@code null} when none was supplied
573	     * @throws DuplicateOwnerEmailException if another owner already uses this email
574	     */
575	    private void rejectDuplicateEmail(String email) {
576	        if (email == null) {
577	            return;
578	        }
579	        boolean inUse = this.clinicService.findAllOwners().stream()
580	            .map(Owner::getEmail)
581	            .filter(existing -> existing != null)
582	            .anyMatch(email::equalsIgnoreCase);
583	        if (inUse) {
584	            throw new DuplicateOwnerEmailException(email);
585	        }
586	    }
587	
588	    /**
589	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
590	     * last name and a normalized address: last names are compared case-insensitively after whitespace
591	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
592	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
593	     * abbreviation still count as the same household.
594	     * <p>
595	     * When the owner's last name and address already belong to at least one other owner the behaviour
596	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
597	     * household. If it is true the create is allowed and every member of the household - the existing
598	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
599	     * read. When no other owner shares the last name and address no identifier is assigned.
600	     *
601	     * @param owner the owner being created
602	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
603	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
604	     *         address and {@code sharesHousehold} is not true
605	     */
606	    /**
607	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
608	     * household member count} for the response.
609	     *
610	     * @param owner the owner to map
611	     * @return the mapped owner DTO
612	     */
613	    private OwnerDto toOwnerDto(Owner owner) {
614	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
615	        return ownerMapper.toOwnerDto(owner);
616	    }
617	
618	    /**
619	     * Counts the members of the given owner's household - the owners that share this owner's
620	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
621	     * is {@code null}) is its own sole member, so the count is one.
622	     *
623	     * @param owner the owner whose household is being sized
624	     * @return the number of owners sharing this owner's household (one when it has no household)
625	     */
626	    private int countHouseholdMembers(Owner owner) {
627	        String householdId = owner.getHouseholdId();
628	        if (householdId == null) {
629	            return 1;
630	        }
631	        return (int) this.clinicService.findAllOwners().stream()
632	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
633	            .count();
634	    }
635	
636	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
637	        String lastName = normalizeHouseholdField(owner.getLastName());
638	        String address = normalizeAddress(owner.getAddress());
639	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
640	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
641	                && normalizeAddress(existing.getAddress()).equals(address))
642	            .toList();
643	        if (housemates.isEmpty()) {
644	            return;
645	        }
646	        if (!Boolean.TRUE.equals(sharesHousehold)) {
647	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
648	        }
649	        String householdId = generateHouseholdId(lastName, address);
650	        owner.setHouseholdId(householdId);
651	        for (Owner housemate : housemates) {
652	            if (!householdId.equals(housemate.getHouseholdId())) {
653	                housemate.setHouseholdId(householdId);
654	                this.clinicService.saveOwner(housemate);
655	            }
656	        }
657	    }
658	
659	    /**
660	     * Builds the stable identifier shared by the members of one household. It is derived purely from
661	     * the normalized last name and address, so every owner of a given household deterministically
662	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
663	     * two normalized fields joined by a single space.
664	     *
665	     * @param normalizedLastName the household's last name, already normalized for comparison
666	     * @param normalizedAddress the household's address, already normalized for comparison
667	     * @return the shared household identifier
668	     */
669	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
670	        String key = normalizedLastName + '�' + normalizedAddress;
671	        try {
672	            byte[] digest = MessageDigest.getInstance("SHA-256")
673	                .digest(key.getBytes(StandardCharsets.UTF_8));
674	            StringBuilder hex = new StringBuilder();
675	            for (byte b : digest) {
676	                hex.append(String.format("%02X", b));
677	                if (hex.length() >= 12) {
678	                    break;
679	                }
680	            }
681	            return hex.substring(0, 12);
682	        } catch (NoSuchAlgorithmException e) {
683	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
684	        }
685	    }
686	
687	    /**
688	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
689	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
690	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
691	     * expands common abbreviations.
692	     *
693	     * @param value the raw last name, or {@code null}
694	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
695	     */
696	    private String normalizeHouseholdField(String value) {
697	        if (value == null) {
698	            return "";
699	        }
700	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
701	    }
702	}
